// One item per PDF or image attachment. Tiny images (logos, e-mail signatures) are skipped.
const bytes = s => { const m = String(s || '').match(/([\d.]+)\s*(B|kB|KB|MB|GB)?/); if (!m) return 0; return Number(m[1]) * ({ B: 1, kB: 1e3, KB: 1e3, MB: 1e6, GB: 1e9 }[m[2] || 'B']); };
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const fromRaw = String(j.from?.value?.[0]?.address || j.from?.text || (typeof j.from === 'string' ? j.from : '') || '');
  const from = (fromRaw.toLowerCase().match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [''])[0];
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const mime = String(bin.mimeType || '').toLowerCase();
    const name = String(bin.fileName || key);
    const isPdf = mime === 'application/pdf' || /\.pdf$/i.test(name);
    const isImg = /^image\/(jpe?g|png|webp|heic|heif)$/.test(mime);
    if (!isPdf && !isImg) continue;
    if (isImg && bytes(bin.fileSize) > 0 && bytes(bin.fileSize) < 20000) continue;
    out.push({ json: { source: 'email', sender_email: from, email_subject: String(j.subject || '').slice(0, 200), message_id: String(j.id || ''),
      received: $now.toFormat('yyyy-MM-dd HH:mm'), file_name: name, mime_type: mime || (isPdf ? 'application/pdf' : 'image/jpeg'), is_pdf: isPdf },
      binary: { file: { ...bin, mimeType: mime || (isPdf ? 'application/pdf' : 'image/jpeg') } } });
  }
}
return out;

// Text from the PDF text layer, or Gemini's transcript of a scan / photo
const base = $('Set invoice settings').item;
const gem = ($json.content?.parts || []).map(p => p.text || '').join('\n');
const text = String($json.text || gem || '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 15000);
return { json: { ...base.json, doc_text: text || '(no readable text)', read_by: $json.content ? 'gemini' : 'pdf text' }, binary: base.binary };

// Maths, date and duplicate checks; one row per document for the Invoices tab
const S = $('Set invoice settings').first().json;
const existing = $('Read invoices for duplicate check').all().map(i => i.json).filter(r => r.invoice_id);

const num = v => { if (v === null || v === undefined || String(v).trim() === '') return null; const n = Number(String(v).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? null : n; };
const norm = s => String(s || '').toLowerCase().replace(/\b(ltd|limited|llc|inc|plc|gmbh|sarl|bv|pty|co)\b\.?/g, '').replace(/[^a-z0-9]/g, '');
const normNo = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/^0+/, '');
const tol = Number(S.tolerance) || 0.05;
const rates = String(S.allowed_tax_rates || '').split(',').map(x => Number(x.trim())).filter(x => !isNaN(x) && String(x) !== '');
const src = $('Prepare text for AI').all();
const seen = [];
function checkOne(f, s) {
  const errors = [], flags = [];
  const type = String(f.document_type || 'other').toLowerCase();
  const net = num(f.net_amount), tax = num(f.tax_amount), total = num(f.total_amount);
  const lines = Array.isArray(f.line_items) ? f.line_items : [];
  if (!f.vendor_name) errors.push('supplier name missing');
  if (!f.invoice_number && type !== 'receipt') errors.push('invoice number missing');
  if (!f.invoice_date) errors.push('invoice date missing');
  if (total === null) errors.push('total missing');
  if (net !== null && tax !== null && total !== null && Math.abs(net + tax - total) > tol)
    errors.push(`net ${net.toFixed(2)} + tax ${tax.toFixed(2)} = ${(net + tax).toFixed(2)}, but the total says ${total.toFixed(2)}`);
  const lineSum = lines.reduce((t, l) => t + (num(l.amount) ?? ((num(l.quantity) ?? 1) * (num(l.unit_price) ?? 0))), 0);
  const base = net ?? (tax === null ? total : null);
  const lineTol = Math.max(tol, lines.length * 0.01);
  if (lines.length && base !== null && Math.abs(lineSum - base) > lineTol && !(total !== null && Math.abs(lineSum - total) <= lineTol))  // VAT-inclusive line prices are fine
    flags.push(`line items add up to ${lineSum.toFixed(2)}, not ${base.toFixed(2)}`);
  lines.forEach((l, k) => { const q = num(l.quantity), u = num(l.unit_price), a = num(l.amount);
    if (q !== null && u !== null && a !== null && Math.abs(q * u - a) > Math.max(tol, Math.abs(a) * 0.01)) flags.push(`line ${k + 1}: ${q} x ${u} is not ${a}`); });
  if (net && tax !== null && rates.length) { const r = tax / net * 100; if (!rates.some(x => Math.abs(x - r) < 0.6)) flags.push(`tax rate ${r.toFixed(1)}% is not one of your rates (${rates.join(', ')}%)`); }
  const d = DateTime.fromISO(String(f.invoice_date || '')), due = DateTime.fromISO(String(f.due_date || ''));
  if (f.invoice_date && !d.isValid) errors.push(`unreadable invoice date "${f.invoice_date}"`);
  if (d.isValid && d > DateTime.now().plus({ days: 1 })) flags.push('invoice date is in the future');
  if (d.isValid && d < DateTime.now().minus({ days: 180 })) flags.push('invoice is more than 6 months old');
  if (d.isValid && due.isValid && due < d) errors.push('due date is before the invoice date');
  if (num(f.confidence) !== null && num(f.confidence) < (Number(S.min_confidence) || 0.7)) flags.push(`AI is unsure about this one (confidence ${num(f.confidence)})`);
  const vkey = norm(f.vendor_name), nkey = normNo(f.invoice_number);
  const pool = [...existing, ...seen].filter(r => String(r.status) !== 'rejected' && String(r.status) !== 'ignored');
  const exact = nkey ? pool.find(r => String(r.vendor_key || norm(r.vendor)) === vkey && normNo(r.invoice_number) === nkey) : null;
  const near = !exact && total !== null && d.isValid ? pool.find(r => String(r.vendor_key || norm(r.vendor)) === vkey && num(r.total) !== null &&
    Math.abs(num(r.total) - total) < 0.01 && Math.abs(DateTime.fromISO(String(r.invoice_date)).diff(d, 'days').days) <= 7) : null;
  if (near) flags.push(`possible duplicate of ${near.invoice_id} (same supplier and total, number ${near.invoice_number || 'none'})`);
  return { type, net, tax, total, lines, errors, flags, vkey, exact, d };
}

const out = [];
$('Extract invoice fields').all().forEach((it, i) => {
  const f = it.json.output || {};
  const s = src[i]?.json || {};
  const c = checkOne(f, s);
  const ignored = !['invoice', 'receipt', 'credit_note'].includes(c.type);
  const status = ignored ? 'ignored' : c.exact ? 'duplicate' : (c.errors.length || c.flags.length) ? 'needs review' : 'ok';
  const row = { invoice_id: 'INV-' + $now.toFormat('yyMMddHHmmss') + '-' + (i + 1), received: s.received, sender_email: s.sender_email,
    file_name: s.file_name, document_type: c.type, vendor: f.vendor_name || '', vendor_key: c.vkey, invoice_number: f.invoice_number || '',
    invoice_date: f.invoice_date || '', due_date: f.due_date || '', currency: f.currency || '', net: c.net ?? '', tax: c.tax ?? '', total: c.total ?? '',
    status, issues: [c.exact ? `duplicate of ${c.exact.invoice_id}` : '', ...c.errors, ...c.flags].filter(Boolean).join(' | '),
    line_items: JSON.stringify(c.lines).slice(0, 4000) };
  seen.push(row);
  out.push({ json: row });
});
return out;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// One summary e-mail per run
const rows = $('Check maths and duplicates').all().map(i => i.json);
const col = { ok: '#1a7f37', 'needs review': '#b54708', duplicate: '#b42318', ignored: '#889' };
const li = rows.map(r => `<li><span style="color:${col[r.status]}"><b>${esc(r.status)}</b></span>: ${esc(r.vendor || r.file_name)} ${esc(r.invoice_number)}
  ${r.total !== '' ? esc(r.currency) + ' ' + Number(r.total).toFixed(2) : ''}${r.due_date ? ', due ' + esc(r.due_date) : ''}${r.issues ? '<br><small>' + esc(r.issues) + '</small>' : ''}</li>`).join('');
const n = s => rows.filter(r => r.status === s).length;
return [{ json: { subject: `Invoices logged: ${rows.length} (${n('needs review')} to review, ${n('duplicate')} duplicate)`,
  html: `<p>New documents from your inbox, logged to the Invoices tab:</p><ul>${li}</ul>` } }];
